 void geometryRoundTripKeepsDraftAndSelection(){QTemporaryDir d;const auto path=d.filePath("gui-state.json");GuiState state(path);QVERIFY(state.load());QVERIFY(state.setSelection("1"));QVERIFY(state.setDraft("1","keep original draft"));const QJsonObject geometry{{"x",-9999},{"y",-9999},{"width",790},{"height",610},{"mode","windowed"}};QVERIFY(state.setGeometry(geometry));QVERIFY(!state.setGeometry({{"x",0},{"y",0},{"width",1},{"height",1},{"mode","windowed"}}));GuiState reopened(path);QVERIFY(reopened.load());QCOMPARE(reopened.geometry(),geometry);QCOMPARE(reopened.selection(),QString("1"));QCOMPARE(reopened.draft("1"),QString("keep original draft"));}
 void completeActivityPayloadUsesBoundManifest(){M3Peer peer;IpcBridge bridge(peer.home.filePath("outbox.json"));bridge.connectToAgent(peer.home.filePath("socket"));QTRY_VERIFY(!bridge.busy());bridge.loadActivityDetails("fixture-operation","fingerprint");QTRY_COMPARE(bridge.activityDetails().value("operationId").toString(),QString("fixture-operation"));bridge.loadActivityPayload("output");QTRY_VERIFY_WITH_TIMEOUT(bridge.sourceDocument()->complete(),5000);QCOMPARE(bridge.sourceDocument()->byteCount(),peer.sourceBody.toUtf8().size());QCOMPARE(bridge.sourceDocument()->payloadManifest().value("subjectId").toString(),QString("fixture-operation"));QByteArray all;for(int i=0;i<bridge.sourceDocument()->pageCount();i++)all+=bridge.sourceDocument()->pageAt(i).toUtf8();QCOMPARE(all,peer.sourceBody.toUtf8());QCOMPARE(peer.submissions.size(),0);QCOMPARE(peer.decisions.size(),0);}
