 void catalogReadyCannotFinishSelectedStream(){M3Peer peer;IpcBridge bridge(peer.home.filePath("outbox.json"));bridge.connectToAgent(peer.home.filePath("socket"));QTRY_VERIFY(!bridge.busy());auto view=peer.view("1");auto chat=view.value("chat").toObject();chat["state"]="running";chat["partial"]=QJsonObject{{"id","partial"},{"text","still streaming"},{"truncated",false}};view["chat"]=chat;auto work=peer.work();work["status"]="running";work["activeConversationId"]="1";work["activeRunId"]="100";view["work"]=work;peer.send({{"v",4},{"epoch",peer.epoch},{"event","conversation.updated"},{"subscriptionId",peer.chatSubscription},{"seq","1"},{"view",view}});QTRY_COMPARE(bridge.partial(),QString("still streaming"));peer.updateCatalog(peer.catalogSubscription,"1");QTRY_COMPARE(bridge.work().value("status").toString(),QString("ready"));QVERIFY(bridge.busy());peer.updateChat(peer.chatSubscription,"2","1");QTRY_VERIFY(!bridge.busy());QVERIFY(bridge.partial().isEmpty());}
