 void oldDaemonShowsProtocolMismatch(){QTemporaryDir d;QLocalServer server;server.setSocketOptions(QLocalServer::UserAccessOption);QVERIFY(server.listen(d.filePath("socket")));int mutations=0;connect(&server,&QLocalServer::newConnection,&server,[&]{auto*c=server.nextPendingConnection();connect(c,&QLocalSocket::disconnected,c,&QObject::deleteLater);connect(c,&QLocalSocket::readyRead,&server,[&,c]{while(c->canReadLine()){const auto f=QJsonDocument::fromJson(c->readLine()).object();if(f.value("method")!="system.hello")mutations++;if(f.value("v")!=2){c->abort();return;}c->write(QJsonDocument(QJsonObject{{"v",2},{"id",f.value("id")},{"epoch","old"},{"ok",false},{"error",QJsonObject{{"code","PROTOCOL_MISMATCH"},{"message","Old daemon"}}}}).toJson(QJsonDocument::Compact)+"\n");}});});IpcBridge bridge(d.filePath("outbox.json"));bridge.connectToAgent(d.filePath("socket"));QTRY_COMPARE_WITH_TIMEOUT(bridge.connectionState(),QString("protocol_mismatch"),4000);QVERIFY(bridge.error().contains("PROTOCOL_MISMATCH"));QVERIFY(bridge.busy());QCOMPARE(mutations,0);}
